from solution import solve

assert solve("") == "", 0
assert solve("A") == "1A", 1
assert solve("AA") == "2A", 2
assert solve("AB") == "1A1B", 3
assert solve("AAABB") == "3A2B", 4
assert solve("ABBA") == "1A2B1A", 5
assert solve("ZZZZZZZZZZZZ") == "12Z", 6
assert solve("ABCABC") == "1A1B1C1A1B1C", 7
assert solve("AAAABCCCC") == "4A1B4C", 8
assert solve("AZZA") == "1A2Z1A", 9
assert solve("") == "1000A", 10
assert solve("XXYYYZ") == "2X3Y1Z", 11
